        self.capacity = capacity
        self._data = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._lock = threading.Lock()

    def get(self, key, default=None):
        with self._lock:
            if key not in self._data:
                self._misses += 1
                return default
            self._hits += 1
            self._data.move_to_end(key)
            return self._data[key]

    def put(self, key, value):
        with self._lock:
            if key in self._data:
                self._data.move_to_end(key)
            self._data[key] = value
            if len(self._data) > self.capacity:
                self._data.popitem(last=False)

    def stats(self):
        with self._lock:
            return {
                "hits": self._hits,
                "misses": self._misses,
                "size": len(self._data),
            }

    def __contains__(self, key):
        with self._lock:
            return key in self._data

    def __len__(self):
        with self._lock:
            return len(self._data)

    def __repr__(self):
        return "LRUCache(capacity={}, size={})".format(
            self.capacity, len(self._data)
        )
```

The race was that `move_to_end` and `popitem` mutate the `OrderedDict`'s internal linked list in place — two threads calling `get`/`put` concurrently can interleave those mutations and corrupt the ordering (or crash). Every method that touches `_data`, `_hits`, or `_misses` now holds `self._lock` for its whole body, so the dict is never observed or mutated by two threads at once. It's a single `threading.Lock`, not a reader/writer lock, so concurrent `get` calls also serialize — fine for a cache at this size, but worth knowing if it becomes a bottleneck.

